package cn.sixnine.filmlog;

import android.app.Instrumentation;
import android.content.*;
import android.database.*;
import android.graphics.*;
import android.net.Uri;
import android.os.*;
import android.provider.DocumentsContract;
import android.provider.DocumentsProvider;
import android.provider.MediaStore;
import androidx.exifinterface.media.ExifInterface;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import org.json.*;
import java.nio.charset.StandardCharsets;

/** Provider and MediaStore tests use only a separate test package and random workspace. */
public final class SharePosterOutputInstrumentation extends Instrumentation {
    int checks;Context context;File source;String authority;
    void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    @Override public void onStart(){Bundle result=new Bundle();boolean ok=false;try{
        check(getTargetContext().getPackageName().endsWith(".tests"),"isolated package");
        context=new WorkspaceContext(getTargetContext(),UUID.randomUUID().toString());authority=getTargetContext().getPackageName()+".poster.documents";
        source=new File(context.getCacheDir(),"output-source.jpg");Bitmap b=Bitmap.createBitmap(640,480,Bitmap.Config.ARGB_8888);b.eraseColor(0xffa86b45);try(FileOutputStream out=new FileOutputStream(source)){check(b.compress(Bitmap.CompressFormat.JPEG,92,out),"fixture");}finally{b.recycle();}
        byte[] original=Files.readAllBytes(source.toPath());
        SharePosterData.Spec one=spec(1,false);Uri protectedUri=document("protected.jpg");byte[] marker={9,8,7,6};try(OutputStream out=context.getContentResolver().openOutputStream(protectedUri,"wt")){out.write(marker);}
        SharePosterOutput.Job protectedJob=SharePosterOutput.start(context,one,protectedUri,false);await(protectedJob);check(!protectedJob.success,"existing target rejected");check(Arrays.equals(marker,read(protectedUri)),"existing target unchanged");
        Uri empty=document("single.jpg");SharePosterOutput.Job single=SharePosterOutput.start(context,one,empty,false);await(single);check(single.success&&single.results.size()==1,"SAF single success");verify(empty,1440);check(SharePosterOutput.active()==null,"slot released after success");
        Uri pipe=document("pipe.jpg");try(OutputStream out=context.getContentResolver().openOutputStream(pipe,"wt")){out.write(original);}Provider.pipeId=DocumentsContract.getDocumentId(pipe);SharePosterData.Item stream=new SharePosterData.Item("pipe","流式照片",null,pipe,0,0,0,false);Bitmap staged=SharePosterRenderer.render(context,new SharePosterData.Spec(Collections.singletonList(stream),false,false,true,"","","","",1440),0,720,new SharePosterRenderer.Control(){public void check(){}public void progress(int d,int t){}});staged.recycle();Provider.pipeId=null;check(new File(context.getCacheDir(),"share-posters").listFiles((d,n)->n.startsWith("source-")).length==0,"nonseekable source staged and cleaned");
        File sourceCache=new File(context.getCacheDir(),"share-posters");sourceCache.mkdirs();File orphan=File.createTempFile("source-orphan-",".tmp",sourceCache);SharePosterOutput.recover(context);check(!orphan.exists(),"interrupted source staging cleaned on entry");
        Uri abandoned=document("interrupted.jpg");String backupBatch=UUID.randomUUID().toString();File journalDir=new File(context.getFilesDir(),"share-poster-journals");journalDir.mkdirs();File backup=new File(journalDir,backupBatch+".json.bak");Files.write(backup.toPath(),journal(backupBatch,"document",abandoned,abandoned,"writing").toString().getBytes(StandardCharsets.UTF_8));SharePosterOutput.recover(context);try(Cursor rows=context.getContentResolver().query(abandoned,new String[]{"_display_name"},null,null,null)){check(rows!=null&&rows.getCount()==0,"backup-only interrupted journal recovered and empty document cleaned");}check(!backup.exists()&&!new File(journalDir,backupBatch+".json").exists(),"recovered backup journal removed");
        Intent send=SharePosterOutput.shareIntent(single.results);check(Intent.ACTION_SEND.equals(send.getAction())&&"image/jpeg".equals(send.getType()),"single share action/type");check(send.getClipData().getItemCount()==1&&(send.getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION)!=0,"single share content grant");
        Uri tree=DocumentsContract.buildTreeDocumentUri(authority,"root");SharePosterOutput.Job multiple=SharePosterOutput.start(context,spec(17,false),tree,true);await(multiple);check(multiple.success&&multiple.results.size()==2,"SAF two pages: "+multiple.message);for(Uri uri:multiple.results)verify(uri,1440);
        Intent sends=SharePosterOutput.shareIntent(multiple.results);check(Intent.ACTION_SEND_MULTIPLE.equals(sends.getAction())&&sends.getClipData().getItemCount()==2,"multiple share clip and action");
        SharePosterOutput.Job progress=new SharePosterOutput.Job(context,spec(43,true),null,false,new SharePosterLayout(43,true,false));progress.page=1;progress.progress(43,43);check(progress.progress==43,"absolute renderer progress not counted twice");
        SharePosterOutput.Job cancelled=SharePosterOutput.start(context,spec(84,true),tree,true);check(SharePosterOutput.active()==cancelled,"one process task slot");cancelled.cancel();if(!cancelled.done){try{SharePosterOutput.start(context,one,tree,true);throw new AssertionError("second live task accepted");}catch(IOException expected){checks++;}}await(cancelled);check(cancelled.cancelled&&!cancelled.success,"cancel never reports success");
        try{SharePosterOutput.shareIntent(Collections.singletonList(Uri.fromFile(source)));throw new AssertionError("file URI accepted");}catch(IOException expected){checks++;}
        try{SharePosterOutput.start(context,spec(17,false),empty,false);throw new AssertionError("multi page single target accepted");}catch(IOException expected){checks++;}
        if(Build.VERSION.SDK_INT>=29){
            SharePosterOutput.Job media=SharePosterOutput.start(context,spec(17,false),null,false);await(media);check(media.success&&media.results.size()==2,"MediaStore two-page success");
            try{for(Uri uri:media.results){verify(uri,1440);try(Cursor c=context.getContentResolver().query(uri,new String[]{"is_pending","relative_path"},null,null,null)){check(c!=null&&c.moveToFirst()&&c.getInt(0)==0,"published only completed page");check(c.getString(1).equals("Pictures/胶片随记/分享图/"),"own output album");}}}finally{for(Uri uri:media.results)context.getContentResolver().delete(uri,null,null);}
            String orphanBatch=UUID.randomUUID().toString();ContentValues pending=new ContentValues();pending.put("_display_name","胶片随记-分享图-"+orphanBatch+"-001.jpg");pending.put("mime_type","image/jpeg");pending.put("relative_path","Pictures/胶片随记/分享图/");pending.put("is_pending",1);Uri orphanUri=context.getContentResolver().insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,pending);check(orphanUri!=null,"orphan pending item created");File orphanJournal=new File(journalDir,orphanBatch+".json");Files.write(orphanJournal.toPath(),journal(orphanBatch,"media",null,null,"planned").toString().getBytes(StandardCharsets.UTF_8));SharePosterOutput.recover(context);try(Cursor rows=context.getContentResolver().query(orphanUri,new String[]{"_id"},null,null,null)){check(rows!=null&&rows.getCount()==0,"created-before-URI-journal pending item safely found and cleaned");}
            ArrayList<SharePosterData.Item> broken=items(17);SharePosterData.Item missing=new SharePosterData.Item("missing","末页缺失",new File(context.getCacheDir(),"not-a-source.jpg"),null,17,0,0,false);broken.set(16,missing);
            SharePosterOutput.Job fail=SharePosterOutput.start(context,new SharePosterData.Spec(broken,false,false,true,"","","","",1440),null,false);await(fail);check(!fail.success&&fail.results.isEmpty()&&fail.partialResults.isEmpty(),"last page failure does not deliver first pending page");
            try(Cursor c=context.getContentResolver().query(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,new String[]{"_id"},"_display_name LIKE ?",new String[]{"胶片随记-分享图-"+fail.batch+"%"},null)){check(c!=null&&c.getCount()==0,"failed pending batch cleaned");}
        }
        check(Arrays.equals(original,Files.readAllBytes(source.toPath())),"original source unchanged");SharePosterOutput.recover(context);check(SharePosterOutput.active()==null,"no live output task at completion");
        result.putString("stream","PASS "+checks+" output assertions: MediaStore, SAF single/tree, target protection, cancel/global slot, progress, content grants, last-page failure and original preservation.\n");ok=true;
    }catch(Throwable e){result.putString("stream",android.util.Log.getStackTraceString(e));}finally{SharePosterOutput.Job job=SharePosterOutput.active();if(job!=null){job.cancel();try{await(job);}catch(Exception ignored){}}}finish(ok?-1:0,result);}
    JSONObject journal(String batch,String mode,Uri destination,Uri page,String state)throws Exception{return new JSONObject().put("version",1).put("batch",batch).put("mode",mode).put("destination",destination==null?"":destination.toString()).put("width",1440).put("finished",false).put("pages",new JSONArray().put(new JSONObject().put("name","胶片随记-分享图-"+batch+"-001.jpg").put("uri",page==null?"":page.toString()).put("state",state)));}
    ArrayList<SharePosterData.Item> items(int n){ArrayList<SharePosterData.Item> list=new ArrayList<>();for(int i=0;i<n;i++)list.add(new SharePosterData.Item("source-"+i,"测试照片",source,null,i+1,0,0,false));return list;}
    SharePosterData.Spec spec(int n,boolean overview){return new SharePosterData.Spec(items(n),overview,false,true,"分享图输出","","","",1440);}
    Uri document(String name)throws Exception{return DocumentsContract.createDocument(context.getContentResolver(),DocumentsContract.buildDocumentUri(authority,"root"),"image/jpeg",name+"-"+UUID.randomUUID());}
    byte[] read(Uri uri)throws Exception{try(InputStream in=context.getContentResolver().openInputStream(uri);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] data=new byte[8192];int n;while((n=in.read(data))!=-1)out.write(data,0,n);return out.toByteArray();}}
    void verify(Uri uri,int width)throws Exception{try(InputStream in=context.getContentResolver().openInputStream(uri)){Bitmap b=BitmapFactory.decodeStream(in);check(b!=null&&b.getWidth()==width&&b.getHeight()==width*5/4,"decode saved JPEG");if(b!=null)b.recycle();}try(InputStream in=context.getContentResolver().openInputStream(uri)){ExifInterface e=new ExifInterface(in);check(e.getAttribute(ExifInterface.TAG_GPS_LATITUDE)==null,"composite GPS absent");}}
    void await(SharePosterOutput.Job job)throws Exception{long until=SystemClock.uptimeMillis()+120000;while(!job.done&&SystemClock.uptimeMillis()<until)SystemClock.sleep(20);check(job.done,"bounded output finishes: "+job.message);}

    public static final class Provider extends DocumentsProvider {
        File root;static volatile String pipeId;
        @Override public boolean onCreate(){if(!getContext().getPackageName().endsWith(".tests"))throw new SecurityException("test-only provider");root=new File(getContext().getCacheDir(),"poster-test-documents");return root.isDirectory()||root.mkdirs();}
        File file(String id)throws FileNotFoundException{if("root".equals(id))return root;if(id==null||!id.matches("[A-Za-z0-9._-]+"))throw new FileNotFoundException("invalid fixture id");return new File(root,id);}
        String[] docColumns(String[] p){return p==null?new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE,DocumentsContract.Document.COLUMN_FLAGS,DocumentsContract.Document.COLUMN_SIZE}:p;}
        void add(MatrixCursor c,File f){MatrixCursor.RowBuilder r=c.newRow();for(String key:c.getColumnNames()){if(key.equals(DocumentsContract.Document.COLUMN_DOCUMENT_ID))r.add(f.equals(root)?"root":f.getName());else if(key.equals(DocumentsContract.Document.COLUMN_DISPLAY_NAME))r.add(f.getName());else if(key.equals(DocumentsContract.Document.COLUMN_MIME_TYPE))r.add(f.isDirectory()?DocumentsContract.Document.MIME_TYPE_DIR:"image/jpeg");else if(key.equals(DocumentsContract.Document.COLUMN_SIZE)||key.equals("_size"))r.add(f.length());else if(key.equals(DocumentsContract.Document.COLUMN_FLAGS))r.add(f.isDirectory()?DocumentsContract.Document.FLAG_DIR_SUPPORTS_CREATE:DocumentsContract.Document.FLAG_SUPPORTS_WRITE|DocumentsContract.Document.FLAG_SUPPORTS_DELETE);else r.add(null);}}
        @Override public Cursor queryRoots(String[] projection){String[] cols=projection==null?new String[]{DocumentsContract.Root.COLUMN_ROOT_ID,DocumentsContract.Root.COLUMN_DOCUMENT_ID,DocumentsContract.Root.COLUMN_TITLE,DocumentsContract.Root.COLUMN_FLAGS}:projection;MatrixCursor c=new MatrixCursor(cols);MatrixCursor.RowBuilder r=c.newRow();for(String key:cols){if(key.equals(DocumentsContract.Root.COLUMN_ROOT_ID)||key.equals(DocumentsContract.Root.COLUMN_DOCUMENT_ID))r.add("root");else if(key.equals(DocumentsContract.Root.COLUMN_TITLE))r.add("分享图隔离测试");else if(key.equals(DocumentsContract.Root.COLUMN_FLAGS))r.add(DocumentsContract.Root.FLAG_SUPPORTS_CREATE);else r.add(null);}return c;}
        @Override public Cursor queryDocument(String id,String[] projection)throws FileNotFoundException{MatrixCursor c=new MatrixCursor(docColumns(projection));File f=file(id);if(f.exists())add(c,f);return c;}
        @Override public Cursor queryChildDocuments(String id,String[] projection,String order)throws FileNotFoundException{MatrixCursor c=new MatrixCursor(docColumns(projection));File[] children=file(id).listFiles();if(children!=null)for(File f:children)add(c,f);return c;}
        @Override public ParcelFileDescriptor openDocument(String id,String mode,CancellationSignal signal)throws FileNotFoundException{if(id.equals(pipeId)&&mode.equals("r")){try{ParcelFileDescriptor[] pipe=ParcelFileDescriptor.createPipe();File source=file(id);new Thread(()->{try(InputStream in=new FileInputStream(source);OutputStream out=new ParcelFileDescriptor.AutoCloseOutputStream(pipe[1])){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}catch(IOException ignored){}},"poster-fixture-pipe").start();return pipe[0];}catch(IOException e){throw new FileNotFoundException("fixture pipe failed");}}return ParcelFileDescriptor.open(file(id),ParcelFileDescriptor.parseMode(mode));}
        @Override public String createDocument(String parent,String mime,String name)throws FileNotFoundException{File target=new File(file(parent),UUID.randomUUID()+".jpg");try{if(!target.createNewFile())throw new IOException();return target.getName();}catch(IOException e){throw new FileNotFoundException("fixture create failed");}}
        @Override public boolean isChildDocument(String parent,String child){try{return "root".equals(parent)&&file(child).isFile();}catch(FileNotFoundException e){return false;}}
        @Override public void deleteDocument(String id)throws FileNotFoundException{if(!file(id).delete())throw new FileNotFoundException("fixture delete failed");}
    }
}
